# SPDX-License-Identifier: AGPL-3.0-only
def solve(payload):
    def parse(i):
        parts = []
        while i < len(payload) and payload[i] != ']':
            char = payload[i]
            if char == '\\':
                parts.append(payload[i + 1])
                i += 2
            elif '0' <= char <= '9':
                start = i
                while '0' <= payload[i] <= '9':
                    i += 1
                count = int(payload[start])
                text, i = parse(i + 1)
                parts.append(text * count)
            else:
                parts.append(char)
                i += 1
        return ''.join(parts), i + 1
    return parse(0)[0]

